#ifndef OFFLINE_API_H
#define OFFLINE_API_H
#include <stdint.h>
#include <stddef.h>
typedef int (*epic_emit_fn)(void *user,int rank,const uint8_t *frame,size_t length);
void *epic_open(int primitive,int mode,int root,uint32_t count,uint32_t words,uint32_t capacity,uint32_t start,epic_emit_fn emit,void *user);
void epic_close(void *context);
int epic_ingress(void *context,int rank,const uint8_t *frame,size_t length);
int epic_flush(void *context);
int epic_retry(void *context,int rank);
void epic_state(void *context,uint64_t *state);
uint64_t epic_digest(void *context);
#endif
#ifndef OFFLINE_PORT_H
#define OFFLINE_PORT_H
#include "offline_api.h"
typedef struct { void *user; int rank; epic_emit_fn emit; } pcap_t;
#endif
